    connection,
    `({
      observedAt: window.__inputObservedAt,
      domUpdatedAt: window.__domUpdatedAt,
      resourceCountAfter: performance.getEntriesByType('resource').length,
      resourceCountBefore: window.__resourceCountBefore,
